catalog_script_client.script:
function onChange( control, oldValue, newValue, isLoading ) {
	console.info( "x_gamlp_idm_lc.On Entity Change Event( " + oldValue + "/" + newValue + " )" );

	if ( g_form.getValue( "running_from" ) == "order_guide" && g_form.getValue( "entity_state" ) == "new" ) {
		console.info( "x_gamlp_idm_lc.On Entity Change Event - Order Guide New" );
		g_form.clearValue( "requested_offering" );
		g_form.setReadOnly( "requested_offering", false );
		return;
	}

	if ( newValue == '' ) {
		g_form.clearValue( "identity" );
	} else if ( newValue && g_form.getValue( "business_service" ) ) {
		var _refreshIdentity = function( entity ) {
			console.info( "x_gamlp_idm_lc.On Entity Change Event._refreshIdentity():" );
			console.info( "x_gamlp_idm_lc.On Entity Change Event._refreshIdentity(): Entity = " + entity );

			var _refreshIdentityCallBack = function( response ) {
				var answer = response.responseXML.documentElement.getAttribute( "answer" );
				console.info( "x_gamlp_idm_lc.On Entity Change Event._refreshIdentityCallBack() - answer = " + answer );
				var result = JSON.parse( answer );

				if ( typeof result !== "undefined" && result.status.code == 0 ) {
					console.info( "x_gamlp_idm_lc.On Entity Change Event._refreshIdentityCallBack() - set Identity -> " + result.mainIdentity.sys_id.value.toString() );
					g_form.setValue( "identity", result.mainIdentity.sys_id.value.toString() );
				} else {
					console.warn( "x_gamlp_idm_lc.On Entity Change Event._refreshIdentityCallBack() - error -> " + result.status.message.message.toString() );
					g_form.clearValue( "identity" );
					g_form.clearValue( "requested_offering" );
					g_form.clearValue( "initial_offering" );
				}

				g_form.setReadOnly( "identity", g_form.getValue( "running_from" ) == "order_guide" );
				g_form.setMandatory( "identity", true );
				g_form.hideFieldMsg( "identity", false );
			};

			g_form.setMandatory( "identity", false );
			g_form.setReadOnly( "identity", true );
			g_form.clearValue( "identity" );

			// g_form.setReadOnly( "requested_offering", true );
			g_form.clearValue( "requested_offering" );
			g_form.clearValue( "initial_offering" );

			g_form.clearMessages();
			g_form.showFieldMsg( "identity", getMessage( "x_gamlp_idm_lc.form.Refreshing" ), "info" );

			var ajax = new GlideAjax( 'x_1610537_rbh_cust.ManageIdentityOfferingsForBusinessServiceUIHelper' );
			ajax.addParam( 'sysparm_name', 'getMainIdentity' );
			ajax.addParam( 'sysparm_entity', entity );
			ajax.getXML( _refreshIdentityCallBack );
		};

		_refreshIdentity( newValue );
	}

}
